// Canonical Workspace registry — the SINGLE source of truth for each top-level Workspace's key,
// display name, and rail icon (a Workspace = a rail destination; see docs/frontend-structure.md).
// The left-nav rail AND the titlebar position crumb both read from here, so a Workspace is named in
// exactly ONE place and the two can never drift: add a Workspace here and it's labeled everywhere
// (rail tooltip + the "you are here" titlebar). Previously the rail's NAV array and App's titlebar
// switch each hardcoded the names independently. (#nav-pass; Screen → Workspace rename #1879)

import {
  TerminalSquare, ScrollText, Settings, Network,
  Component, Users, Binary, Database, AudioLines, KeyRound, Brain,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";

/** Every top-level Workspace key (a rail destination). The store's `activeWorkspace` is one of these. */
// "design" (Design Studio) and "algorithms" (the knowledge graph) were removed as rail Workspaces —
// each is a single page, now a Planner tab (projectsPageMode "designs" / "algorithms"). A persisted
// `activeWorkspace: "design" | "algorithms"` is migrated to projects + the matching page mode.
// "skills" went the same way (skills-move-to-teams-and-pair-with-personas): a skill is injectable
// agent CONTEXT, so it lives on the TEAMS page beside the personas that carry it, and a persisted
// `activeWorkspace: "skills"` migrates to projects + the "teams" page mode.

// "security" became "logs" (the-logs-workspace-scaffold-and-activity): three of its four tabs were

// deleted and the survivor — Activity, an audit FEED — is history, so it opens the unified Logs

// screen instead of holding a workspace of its own. A persisted `activeWorkspace: "security"`

// migrates to "logs"; so does the older "agents", which used to redirect to "security".

// "automation" is gone too (hooks-and-schedules-belong-to-the-persona): its CONFIG -- hooks and

// schedules -- is carried by the persona that runs it and read on the Teams page, and its

// HISTORY is the Logs -> Automations tab. A persisted `activeWorkspace: "automation"` migrates

// to Teams, which is where the thing it used to edit now lives.
// "projects" (the Planner) is gone (delete-the-planner-ui-keep-the-planner): its screen was the
// pitch-to-plan CONVERSATION, and planning is the director's job now — the architect runs discovery
// with the user, then creates a director that completes the plan and designs its team. The planner's
// FUNCTIONS are untouched: 142 React-free modules, `src-tauri/src/planner`, the fleet, and plan.db all
// remain, driven through `bsc plan` / `bsc publish` / `bsc fleet start`. A persisted
// `activeWorkspace: "projects"` migrates to GLANCE, which is where projects are seen.
// "github" is gone (delete-the-github-screen-keep-the-integration): the SCREEN was 22 records of
// repo/PR/insight charts over an API the app no longer needs a browser for. The INTEGRATION stays —
// `src-tauri/src/github` still runs publish and readiness, and Settings → GitHub is still where an
// account is connected. A persisted `activeWorkspace: "github"` migrates to Settings → GitHub, which
// is where GitHub still exists in the app.
// "mcp" is gone too (mcp-moves-to-teams): an MCP server is injectable agent CAPABILITY, the same
// class of thing as a skill, so it is READ on the Teams page beside the agents that get it rather
// than owning a rail destination. A persisted `activeWorkspace: "mcp"` migrates to the Teams page.
export type Workspace =
  | "console" | "glance" | "logs" | "settings"
  // The five GRAPHS (`five-graphs-become-rail-workspaces`). Each was a Planner tab; each is now its
  // own rail destination, because the graphs ARE the app. This REVERSES the collapses recorded above
  // — `design` and `algorithms` came back out, and `teams`/`sounds`/`data` came with them — so the
  // redirects in `store/retiredWorkspaces.ts` had to be REVERSED, not extended: every one of them
  // pointed at a Planner page that no longer exists.
  | "components" | "teams" | "algorithms" | "data" | "sounds"
  // The CREDENTIAL store (`a-credentials-workspace-shows-the-state-of-every-credential`). NOT a
  // graph — a utility, so it sits with Logs and Settings rather than inside the graph group. It is
  // a rail destination because a credential that has quietly expired is invisible everywhere else:
  // the OS keychain has no listing, so before this screen the only way to discover a broken pairing
  // was an agent's call failing mid-task.
  | "credentials"
  // SESSION MEMORY (`a-memory-workspace-shows-what-we-know`). Also a utility rather than a sixth
  // graph, and for a sharper reason than Credentials: the other graphs describe what the app IS
  // MADE OF and are AUTHORING surfaces, while memory is what we have LEARNED ABOUT it. Putting it
  // in the graph group would claim in the chrome that a lesson is a pillar of the product.
  | "memory";

export interface WorkspaceMeta {
  key: Workspace;
  /** The page's display name — the rail tooltip AND the titlebar position crumb. */
  label: string;
  Icon: LucideIcon;
}

/** Rail order is product-defined (#872) and locked by rail.test.tsx; the titlebar reads the
 *  same labels. Adding a screen is one entry here. */
export const WORKSPACES: WorkspaceMeta[] = [
  { key: "console",    label: "Console",     Icon: TerminalSquare },
  { key: "glance",     label: "Glance",      Icon: Network },
  // The five GRAPHS, kept together and in this order deliberately: Components and Algorithms lead
  // because they are the two whose technology axis is real in the data today; the three whose axis
  // is newer follow. They sit between the workflow destinations above and the utilities below.
  { key: "components", label: "Components",  Icon: Component },
  { key: "teams",      label: "Teams",       Icon: Users },
  { key: "algorithms", label: "Algorithms",  Icon: Binary },
  { key: "data",       label: "Data",        Icon: Database },
  { key: "sounds",     label: "Sounds",      Icon: AudioLines },
  // Utilities. Memory leads them, immediately after the graphs it is mostly ABOUT — most of its
  // edges point at a graph record, so the two are read together. Credentials follows: it is the one
  // that can be WRONG, and a destination you only visit when something is broken has to be easy to
  // find.
  { key: "memory",     label: "Memory",      Icon: Brain },
  { key: "credentials", label: "Credentials", Icon: KeyRound },
  { key: "logs",       label: "Logs",        Icon: ScrollText },
  { key: "settings",   label: "Settings",    Icon: Settings },
];

const BY_KEY = Object.fromEntries(WORKSPACES.map((s) => [s.key, s])) as Record<Workspace, WorkspaceMeta>;

/** The canonical display name for a Workspace — the rail tooltip and the titlebar position crumb.
 *  Falls back to the raw key for an unknown Workspace so an unmapped page is still visibly labeled
 *  (never blank). */
export function workspaceLabel(key: Workspace): string {
  return BY_KEY[key]?.label ?? key;
}

/** The Workspace to actually render for a raw store `activeWorkspace`. Identity now that Console is a
 *  permanent rail workspace (the `showConsolePage` opt-in, #2372, is gone) — kept as the single
 *  indirection the App shell and `useHotkeys` share so any future workspace redirect has one home. */
export function effectiveWorkspace(raw: Workspace): Workspace {
  return raw;
}
